<?php $row = $data['entry']; $rights = $data['file_caps']; ?>
<div class="page-heading"><div><p class="eyebrow">DATEIABLAGE</p><h1><?= $e($row['name']) ?></h1><p class="lead"><?= $row['kind'] === 'folder' ? 'Ordner' : 'Datei' ?></p></div><a class="button button-outline" href="<?= $e('/files?' . http_build_query(['space' => $data['space_id'], 'parent' => $row['parent_id']])) ?>">Zurück zum Ordner</a></div>
<?php if(isset($data['form_error'])): ?><p><a target="_blank" rel="noopener" href="<?= $e('/files/detail?'.http_build_query(['space'=>$data['space_id'],'entry'=>$row['id']])) ?>">Aktuellen Stand in neuem Tab öffnen</a></p><?php endif ?>
<div class="file-toolbar"><?php if($row['kind']==='file'&&$rights['read']): ?><a class="button" href="<?= $e('/files/download?'.http_build_query(['space'=>$data['space_id'],'entry'=>$row['id']])) ?>">Herunterladen</a><?php endif ?><?php if($row['kind']==='file'&&($data['can_catalog']??false)): ?><p><a class="button button-outline" href="<?= $e('/catalog?'.http_build_query(['space'=>$data['space_id'],'entry'=>$row['id']])) ?>">Beschreibung und Tags</a></p><?php endif ?>
<?php if ($row['kind'] === 'file' && $rights['read'] && (int) $row['size_bytes'] <= \Samla\Core\Storage\TextDocument::MAX_BYTES && \Samla\Core\Storage\TextDocument::supports($row['name'])): ?><p><a class="button button-outline" href="<?= $e('/files/edit?' . http_build_query(['space' => $data['space_id'], 'entry' => $row['id']])) ?>">Text öffnen</a></p><?php endif ?>
</div>
<section class="panel"><div class="panel-heading"><h2>Aktionen</h2></div><div class="group-list">
<?php
$actions = [];
if ($rights['update']) { $actions['rename'] = 'Umbenennen'; }
if ($rights['update'] && $rights['create'] && $rights['delete']) { $actions['move'] = 'Verschieben'; }
if ($row['kind'] === 'file' && $rights['read'] && $rights['create']) { $actions['copy'] = 'Datei kopieren'; }
if ($rights['delete']) { $actions['trash'] = 'In den Papierkorb'; }
?>
<?php foreach ($actions as $action => $label): ?><details class="file-action" <?= ($data['retry_operation']??'')===$action?'open':'' ?>><summary><?= $e($label) ?></summary><form class="group-row settings-form" method="post" action="/files/change"><div><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space_id']) ?>"><input type="hidden" name="entry" value="<?= $e($row['id']) ?>"><input type="hidden" name="operation" value="<?= $e($action) ?>"><input type="hidden" name="expected_name" value="<?= $e($data['expected_name']??$row['name']) ?>"><input type="hidden" name="expected_parent" value="<?= $e($data['expected_parent']??$row['parent_id']) ?>">
<?php if (in_array($action, ['rename','copy'], true)): ?><label for="name-<?= $e($action) ?>">Neuer Name</label><input id="name-<?= $e($action) ?>" name="name" value="<?= $e($data['submitted_name']??$row['name']) ?>" required maxlength="255"><?php endif ?>
<?php if (in_array($action, ['move','copy'], true)): ?><label for="parent-<?= $e($action) ?>">Zielordner</label><select id="parent-<?= $e($action) ?>" name="parent"><?php foreach ($data['destinations'] as $folderId => $folderName): ?><?php if ($folderId === $row['id']) { continue; } ?><option value="<?= $e($folderId) ?>" <?= ($data['submitted_parent']??'')===$folderId?'selected':'' ?>><?= $e($folderName) ?></option><?php endforeach ?></select><p class="field-note">Die Auswahl zeigt bis zu 100 Ordner dieses Bereichs.</p><?php else: ?><input type="hidden" name="parent" value="<?= $e($row['parent_id']) ?>"><?php endif ?>
</div><button class="button button-outline" type="submit"><?= $e($label) ?></button></form></details><?php endforeach ?>
<?php if ($actions === []): ?><p class="empty">Für diesen Eintrag sind keine Änderungen freigegeben.</p><?php endif ?></div></section>
<?php if ($row['kind'] === 'file' && $rights['read'] && $rights['versions.read']): ?><p><a class="button button-outline" href="<?= $e('/files/versions?' . http_build_query(['space' => $data['space_id'], 'entry' => $row['id']])) ?>">Dateiversionen ansehen</a></p><?php endif ?>
<?php if ($row['kind'] === 'file' && $rights['update']): ?><details class="panel file-action"><summary>Dateiinhalt ersetzen</summary><div class="disclosure-content"><p>Der bisherige Inhalt bleibt als Version erhalten. Der Dateiname bleibt bestehen.</p><form method="post" action="/files/replace" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space_id']) ?>"><input type="hidden" name="entry" value="<?= $e($row['id']) ?>"><input type="hidden" name="parent" value="<?= $e($row['parent_id']) ?>"><input type="hidden" name="revision" value="<?= $e($row['revision']) ?>"><label for="replacement">Neuer Dateiinhalt</label><input id="replacement" type="file" name="file" required><button class="button" type="submit">Neue Version speichern</button></form></div></details><?php endif ?>

